import { ColorInput } from '@/lib/designsystem';
import { useState } from 'react';

export default function ColorPickerExample() {
  const [color, setColor] = useState('#5C62D6');

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setColor(event.target.value);
  };

  return (
    <ColorInput
      id="base-color"
      label="Base Color"
      value={color}
      onChange={handleChange}
      helperText="Select the primary base color for the theme."
      required
    />
  );
}
